// ===== ModesServer Wrapper =====

struct mavsdk_modes_server_wrapper {
    std::shared_ptr<mavsdk::ModesServer> cpp_plugin;
};

mavsdk_modes_server_t
mavsdk_modes_server_create(mavsdk_server_component_t server_component) {
    if (server_component == nullptr) {
        return nullptr;
    }

    auto wrapper = new mavsdk_modes_server_wrapper();
    auto server_component_ptr = reinterpret_cast<std::shared_ptr<mavsdk::ServerComponent>*>(server_component);
    wrapper->cpp_plugin = std::make_shared<mavsdk::ModesServer>(*server_component_ptr);

    return reinterpret_cast<mavsdk_modes_server_t>(wrapper);
}

void mavsdk_modes_server_destroy(mavsdk_modes_server_t modes_server) {
    if (modes_server == nullptr) {
        return;
    }

    // Releasing the handles is the caller's job. Dropping the plugin marks every
    // subscription of it dead anyway, so nothing can fire into it after this.
    delete reinterpret_cast<mavsdk_modes_server_wrapper*>(modes_server);
}

// ===== Method Implementations =====


// SetAvailableModes sync
mavsdk_modes_server_result_t
mavsdk_modes_server_set_available_modes(
    mavsdk_modes_server_t modes_server,
    const mavsdk_modes_server_mode_t* modes,
    size_t modes_size)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_server_wrapper*>(modes_server);

    auto ret_value = wrapper->cpp_plugin->set_available_modes(        [&modes, modes_size]() {
            std::vector<mavsdk::ModesServer::Mode> vec;
            vec.reserve(modes_size);
            for (size_t i = 0; i < modes_size; i++) {
                vec.push_back(translate_mode_from_c(modes[i]));
            }
            return vec;
        }());

    return translate_result(ret_value);
}
